struct CliProcessResult {DWORD exit_code=1;std::string output,error;};
std::wstring quote_argument(const std::wstring& value){
    if(!value.empty()&&value.find_first_of(L" \t\n\v\"")==std::wstring::npos)return value;
    std::wstring result=L"\"";std::size_t slashes=0;
    for(const auto ch:value){if(ch==L'\\'){++slashes;continue;}if(ch==L'\"'){result.append(slashes*2+1,L'\\');result.push_back(ch);slashes=0;continue;}result.append(slashes,L'\\');slashes=0;result.push_back(ch);}
    result.append(slashes*2,L'\\');result.push_back(L'\"');return result;
}
CliProcessResult run_cli(const std::filesystem::path& executable,const std::filesystem::path& folder,int port,const std::string& session,const std::string& input){
    const auto input_path=folder/L"multi-branch-cli.stdin",output_path=folder/L"multi-branch-cli.stdout",error_path=folder/L"multi-branch-cli.stderr";
    {std::ofstream stream(input_path,std::ios::binary);stream<<input;if(!stream)throw std::runtime_error("Could not write interactive CLI fixture input");}
    SECURITY_ATTRIBUTES security{sizeof(SECURITY_ATTRIBUTES),nullptr,TRUE};
    HANDLE child_input=CreateFileW(input_path.c_str(),GENERIC_READ,FILE_SHARE_READ,&security,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
    HANDLE child_output=CreateFileW(output_path.c_str(),GENERIC_WRITE,FILE_SHARE_READ,&security,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);
    HANDLE child_error=CreateFileW(error_path.c_str(),GENERIC_WRITE,FILE_SHARE_READ,&security,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);
    if(child_input==INVALID_HANDLE_VALUE||child_output==INVALID_HANDLE_VALUE||child_error==INVALID_HANDLE_VALUE){for(const auto handle:{child_input,child_output,child_error})if(handle!=INVALID_HANDLE_VALUE)CloseHandle(handle);throw std::runtime_error("Could not create interactive CLI standard streams");}
    STARTUPINFOW startup{};startup.cb=sizeof(startup);startup.dwFlags=STARTF_USESTDHANDLES;startup.hStdInput=child_input;startup.hStdOutput=child_output;startup.hStdError=child_error;
    PROCESS_INFORMATION process{};auto command=quote_argument(executable.wstring())+L" "+std::to_wstring(port)+L" chat "+quote_argument(std::wstring(session.begin(),session.end()));
    std::vector<wchar_t> command_line(command.begin(),command.end());command_line.push_back(L'\0');
    std::vector<wchar_t> previous(32768);const DWORD old_length=GetEnvironmentVariableW(L"XMIND_AUTH_TOKEN",previous.data(),static_cast<DWORD>(previous.size()));const bool had_previous=old_length>0&&old_length<previous.size();
    if(!SetEnvironmentVariableW(L"XMIND_AUTH_TOKEN",L"synthetic-dynamic-engine-http-access-token")){CloseHandle(child_input);CloseHandle(child_output);CloseHandle(child_error);throw std::runtime_error("Could not prepare the authenticated CLI environment");}
    const BOOL created=CreateProcessW(executable.c_str(),command_line.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,folder.c_str(),&startup,&process);
    SetEnvironmentVariableW(L"XMIND_AUTH_TOKEN",had_previous?previous.data():nullptr);
    CloseHandle(child_input);CloseHandle(child_output);CloseHandle(child_error);
    if(!created)throw std::runtime_error("Could not start the actual xmind_cli process");
    const DWORD waited=WaitForSingleObject(process.hProcess,30000);if(waited!=WAIT_OBJECT_0){TerminateProcess(process.hProcess,124);WaitForSingleObject(process.hProcess,5000);CloseHandle(process.hThread);CloseHandle(process.hProcess);throw std::runtime_error("Interactive xmind_cli did not finish within 30 seconds");}
    CliProcessResult result;if(!GetExitCodeProcess(process.hProcess,&result.exit_code)){CloseHandle(process.hThread);CloseHandle(process.hProcess);throw std::runtime_error("Could not inspect xmind_cli exit status");}
    CloseHandle(process.hThread);CloseHandle(process.hProcess);result.output=read(output_path);result.error=read(error_path);return result;
}
#endif
